-- preflight for 62-65 (SELECT only): target sets - existing drafts, attempts, R&W hard counts in M1/M2-lower; already-imported hard gids
-- generated by scripts/prod-open/sat-rw-hard-sql.ts. Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched.

select s.name, s.version_no, s.status,
  (select count(*) filter (where i.difficulty = 'hard') from mock_exam_set_items i where i.exam_set_id = s.id and i.section = 'rw' and (i.module_key = 'rw_m1' or i.route = 'lower')) as rw_hard_m1_lower,
  (select count(*) from mock_exam_sets d where d.set_group_id = s.set_group_id and d.status = 'draft' and d.archived_at is null) as existing_drafts,
  (select count(*) from mock_exam_attempts a where a.exam_set_id = s.id) as attempts
from mock_exam_sets s where s.name = any (array['SAT Practice Test 1','SAT Practice Test 2','SAT Practice Test 3','SAT Practice Test 4','SAT Practice Test 5','SAT Practice Test 6','SAT Practice Test 7','SAT Practice Test 8','SAT Practice Test 9','SAT Practice Test 10','SAT Practice Test 11','SAT Practice Test 12','SAT Practice Test 13','SAT Practice Test 14','SAT Practice Test 15','SAT Practice Test 16','SAT Practice Test 17','SAT Practice Test 18','SAT Practice Test 19','SAT Practice Test 20','SAT Practice Test 21','SAT Practice Test 22','SAT Practice Test 23','SAT Practice Test 24','SAT Practice Test 25','SAT Practice Test 26','SAT Practice Test 27','SAT Practice Test 28','SAT Practice Test 29','SAT Practice Test 30']) and s.status = 'published' and s.archived_at is null order by length(s.name), s.name;
